using System;using System.IO;using System.Text;using System.Security.Cryptography;using FocusGrowth;
class SessionTests {
 static int pass;static void Check(bool x){if(!x)throw new Exception("assertion_failed");pass++;}
 static string B(byte[] x){return Convert.ToBase64String(x).TrimEnd('=').Replace('+','-').Replace('/','_');}
 static void Denied(Action a){try{a();}catch(Fault){pass++;return;}throw new Exception("expected_rejection");}
 static int Main(string[] args){try{var t=new DateTime(2026,11,22,0,0,0,DateTimeKind.Utc);var disk=new Disk(args[0]);var s=new DeviceSessions(disk,()=>t);string origin=Bridge.Pages;using(var rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;var key=rsa.ExportParameters(false);string id=s.Enroll(origin,B(key.Modulus),B(key.Exponent));Check(s.Active(id,origin));Check(!s.Active(id,"https://attacker.invalid"));string nonce=s.Challenge(id,origin,"resume");string sig=B(rsa.SignData(Encoding.UTF8.GetBytes(DeviceSessions.Message(id,origin,"resume",nonce)),CryptoConfig.MapNameToOID("SHA256")));s.Prove(id,origin,"resume",nonce,sig);pass++;Denied(()=>s.Prove(id,origin,"resume",nonce,sig));var restarted=new DeviceSessions(disk,()=>t);Check(restarted.Active(id,origin));t=t.AddHours(23);nonce=restarted.Challenge(id,origin,"resume");sig=B(rsa.SignData(Encoding.UTF8.GetBytes(DeviceSessions.Message(id,origin,"resume",nonce)),CryptoConfig.MapNameToOID("SHA256")));restarted.Prove(id,origin,"resume",nonce,sig);t=t.AddHours(1);Check(restarted.Active(id,origin));id=s.Enroll(origin,B(key.Modulus),B(key.Exponent));t=t.AddHours(23);nonce=s.Challenge(id,origin,"activity");sig=B(rsa.SignData(Encoding.UTF8.GetBytes(DeviceSessions.Message(id,origin,"activity",nonce)),CryptoConfig.MapNameToOID("SHA256")));s.Prove(id,origin,"activity",nonce,sig);t=t.AddHours(2);Check(s.Active(id,origin));t=t.AddDays(15);Check(s.Active(id,origin));id=s.Enroll(origin,B(key.Modulus),B(key.Exponent));nonce=s.Challenge(id,origin,"resume");Denied(()=>s.Prove(id,origin,"resume",nonce,"AAAA"));Denied(()=>s.Prove(id,origin,"resume",nonce,"AAAA"));Check(!s.Active(id,origin));id=s.Enroll(origin,B(key.Modulus),B(key.Exponent));nonce=s.Challenge(id,origin,"resume");t=t.AddSeconds(31);Denied(()=>s.Prove(id,origin,"resume",nonce,"AAAA"));s.Revoke(id,origin);Check(!new DeviceSessions(disk,()=>t).Active(id,origin));id=s.Enroll(origin,B(key.Modulus),B(key.Exponent));s.RevokeAll();Check(!new DeviceSessions(disk,()=>t).Active(id,origin));Denied(()=>s.Challenge(id,origin,"activity"));}Console.WriteLine("PASS "+pass+" synthetic session core checks");return 0;}catch{Console.WriteLine("FAIL session core checks");return 1;}}
}
